# File: merge-vs-rebase.sh — two ways to integrate, different history.

# ---- REBASE: keep the PRIVATE feature branch current + LINEAR ----
git checkout feature/fraud-check
git fetch origin
git rebase origin/main          # replay my commits onto latest main (new hashes)
# history becomes a straight line; use ONLY on this unshared branch.

# ---- MERGE: integrate the feature INTO shared main (preserve history) ----
git checkout main
git pull origin main
git merge --no-ff feature/fraud-check   # --no-ff forces a merge commit
# creates a merge commit with TWO parents; nothing rewritten; honest history.
git push origin main
```

```bash
# File: stash-around-interruption.sh — shelve uncommitted work.

# Mid-feature, dirty working dir, a PRODUCTION alert arrives.
git status                      # fraud changes not committed

# Shelve ALL uncommitted tracked changes; working tree becomes clean.
git stash push -m "wip fraud velocity check"

# Switch to fix the emergency on another branch, deploy, come back.
git checkout hotfix/urgent
# ... fix, commit, deploy ...
git checkout feature/fraud-check

# Reapply the shelved work and continue; 'pop' also drops it from the stack.
git stash list                  # see shelved entries
git stash pop                   # restore "wip fraud velocity check"
```

```bash
# File: cherry-pick-one-fix.sh — copy ONE commit across branches.

# A single valuable fix exists on the release branch:
git log --oneline release/1.5 -3
#   9abc123 FRD-88 fix false-positive on international cards   <-- want THIS one
#   7def456 unrelated release prep
#   5aaa789 unrelated docs

# Bring JUST that commit onto main (new commit, new hash, same change).
git checkout main
git cherry-pick 9abc123
# resolve any conflict, then: git cherry-pick --continue
git push origin main
```

