package com.bank.fraud;

import java.math.BigDecimal;

// The feature flowing through rebase/merge; the cherry-picked fix adjusts it.
public class FraudCheckService {

    private static final BigDecimal HIGH_VALUE = new BigDecimal("500000");

    // Flag a transaction as suspicious above a threshold. The cherry-picked
    // fix FRD-88 stops flagging legitimate international cards below the limit.
    public boolean isSuspicious(BigDecimal amount, boolean internationalCard) {
        if (internationalCard && amount.compareTo(HIGH_VALUE) <= 0) {
            // FRD-88: do NOT flag normal international spend under the limit.
            return false;
        }
        return amount.compareTo(HIGH_VALUE) > 0;
    }
}
