package com.bank.fraud;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

class FraudCheckServiceTest {

    private final FraudCheckService service = new FraudCheckService();

    @Test
    void flagsHighValue() {
        assertTrue(service.isSuspicious(new BigDecimal("600000"), false));
    }

    @Test
    void doesNotFlagNormalInternational() {
        // After FRD-88: Priya's 200000 international spend is NOT suspicious.
        assertFalse(service.isSuspicious(new BigDecimal("200000"), true));
    }
}
